import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.Cs5aHXsR.js";var i=JSON.parse(`{"title":"What is woodpecker-ci-mcp?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1787828411000}`),a={name:`guide/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="what-is-woodpecker-ci-mcp" tabindex="-1">What is woodpecker-ci-mcp? <a class="header-anchor" href="#what-is-woodpecker-ci-mcp" aria-label="Permalink to “What is woodpecker-ci-mcp?”">​</a></h1><p>An MCP server for <a href="https://woodpecker-ci.org" target="_blank" rel="noreferrer">Woodpecker CI</a>, the lightweight, container-native CI engine that grew out of Drone. Woodpecker runs your pipelines; this server puts what they did — and the ability to do something about it — inside an MCP client.</p><p>It speaks the Woodpecker API and was written against, and verified on, a 3.18.0 instance.</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>Because the interesting question is never &quot;did it go red&quot;. You can see that on the dashboard. The interesting question is the next one: <em>which step failed</em>, <em>what did it print</em>, <em>was it the same last night</em>, <em>and can we just run it again</em>. Answering that means the pipeline list, then one pipeline&#39;s steps, then that step&#39;s log — three lookups a model chains in one turn and a person does by clicking, in a UI, in another tab.</p><p>The second reason is that reading is only half of it. Every other Woodpecker MCP server stops at the read tools, and the moment you know what broke you are back in the web UI anyway: to restart the pipeline, to approve the one waiting on a human, to fix the cron that fires an hour off, to rotate the secret a step just printed into a log. Those are the tools this server has, behind confirmation tokens where they cannot be undone.</p><h2 id="what-it-looks-like" tabindex="-1">What it looks like <a class="header-anchor" href="#what-it-looks-like" aria-label="Permalink to “What it looks like”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; Why did the last pipeline on development fail?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  list_pipelines(repo_id: 21, branch: &quot;development&quot;, status: &quot;failure&quot;)</span></span>
<span class="line"><span>  get_pipeline(repo_id: 21, number: 1014)</span></span>
<span class="line"><span>  get_step_logs(repo_id: 21, number: 1014, step_id: 84190)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Step &quot;test&quot; exited 1. The last lines are a failing assertion in</span></span>
<span class="line"><span>  UserServiceTest — a NullPointerException at UserService.java:212.</span></span>
<span class="line"><span>  The step before it, &quot;build&quot;, succeeded.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt; Restart it.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  restart_pipeline(repo_id: 21, number: 1014)</span></span>
<span class="line"><span>  Restarted as pipeline 1016.</span></span></code></pre></div><h2 id="what-it-will-not-do" tabindex="-1">What it will not do <a class="header-anchor" href="#what-it-will-not-do" aria-label="Permalink to “What it will not do”">​</a></h2><p>The tool surface stops short in four places, all deliberate:</p><ul><li>It cannot read out or rotate <strong>its own access token</strong>. <code>POST /user/token</code> and <code>DELETE /user/token</code> exist in the API and are not tools here.</li><li>It cannot <strong>forge a webhook</strong>. <code>POST /hook</code> would let a model start a pipeline while making it look as though somebody pushed a commit. <code>trigger_pipeline</code> is the honest version and is marked as a manual event.</li><li>It does not hand over <strong>agent tokens</strong> on read, because the API does — see <a href="/guide/security">security</a>.</li><li>It does not stream. Server-sent events do not fit a request/response tool, so there is nothing to subscribe to; poll <code>get_pipeline</code>.</li></ul><h2 id="where-next" tabindex="-1">Where next <a class="header-anchor" href="#where-next" aria-label="Permalink to “Where next”">​</a></h2><ul><li><a href="/guide/getting-started">Getting started</a> — a token and three lines of config.</li><li><a href="/guide/clients">Connecting clients</a> — Claude Code, Claude Desktop, Codex, Docker, mcp-hub.</li><li><a href="/guide/configuration">Configuration</a> — and how to cut 71 tools down to the ones you want.</li><li><a href="/reference/tools">Tools reference</a> — every tool and its parameters.</li></ul>`,13)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};